<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ensureDays, openEditor, state } from '../store';
import { route, navigate } from '../router';
import { addDays, displayDate } from '../domain/dates';
import { extractCycles } from '../domain/cycles';
import { buildObservations, cycleBodyStatistics, cycleStatistics, dailyStatistics, periodStatistics } from '../domain/statistics';
import { meanAbsoluteError } from '../domain/evaluation';
import TrendChart from '../components/TrendChart.vue';
import Icon from '../components/Icon.vue';
const tab = ref('cycles'), error = ref(''), loading = ref(false);
const cycles = computed(() => extractCycles(state.facts.periods,state.facts.bleeding.filter(b => b.bleedingType === 'UNKNOWN').map(b => b.date)));
const cycleStats = computed(() => cycleStatistics(cycles.value,route.cycles));
const periodStats = computed(() => periodStatistics(state.facts.periods,route.cycles));
const start = computed(() => addDays(state.today,1-route.days));
const logs = computed(() => Object.values(state.days).sort((a,b) => a.date.localeCompare(b.date)));
const daily = computed(() => dailyStatistics(logs.value,start.value,state.today));
const bodyCycles = computed(() => cycleBodyStatistics(state.facts.periods,logs.value,route.cycles));
const observations = computed(() => buildObservations(cycles.value,state.facts.periods,logs.value,state.today));
const mae = computed(() => meanAbsoluteError(state.evaluations));
const cycleRows = computed(() => cycleStats.value.rows.map(c => ({ date: c.endDate,value: c.length,breakBefore: cycles.value.slice(0,cycles.value.indexOf(c)).at(-1)?.exclusion !== null })));
watch([start,() => route.cycles,() => state.revision],async () => { loading.value = true; try { const since = [addDays(state.today,-Math.max(59,route.days-1)),periodStats.value.rows[0]?.startDate].filter(Boolean).sort()[0]!; await ensureDays(since,state.today); error.value = ''; } catch (e) { error.value = (e as Error).message; } finally { loading.value = false; } },{ immediate: true });
const fixed = (n: number | null) => n === null ? '—' : n.toFixed(1);
function rangeCycles(value: number) { navigate('insights',{ cycles: value,days: route.days }); }
function rangeDays(value: number) { navigate('insights',{ cycles: route.cycles,days: value }); }
</script>
<template><div class="page insights-page"><header class="page-heading"><div><p class="eyebrow">把记录连起来，看见自己的变化</p><h1>慢慢了解自己的规律</h1><p class="page-subtitle">每个数字都来自你实际留下的记录。</p></div><Icon name="insights" :size="30" /></header>
  <div class="insights-tabs segmented"><button v-for="[value,label] in [['cycles','周期'],['body','身体记录'],['observations','个人观察']]" :key="value" :class="{ active: tab === value }" @click="tab = value">{{ label }}</button></div>
  <template v-if="tab === 'cycles'"><div class="section-heading row-between"><h2>周期里的变化</h2><div class="chips range-chips"><button v-for="n in [3,6,12]" :key="n" :class="{ selected: route.cycles === n }" :disabled="n > 3 && cycles.filter(c => !c.exclusion).length < n" @click="rangeCycles(n)">最近 {{ n }} 次</button></div></div>
    <div class="stats-grid"><section class="card stat-card"><span>平均周期</span><strong>{{ fixed(cycleStats.mean) }}<small>天</small></strong><p>{{ cycleStats.sampleCount }} 个有效周期</p></section><section class="card stat-card"><span>周期波动</span><strong>{{ fixed(cycleStats.std) }}<small>天</small></strong><p>样本标准差 · 越大表示差异越大</p></section><section class="card stat-card"><span>经期长度中位数</span><strong>{{ fixed(periodStats.median) }}<small>天</small></strong><p>{{ periodStats.sampleCount }} 次完整经期</p></section></div>
    <section class="card"><div class="row-between"><h2>周期长度</h2><span class="hint">{{ cycleStats.min === null ? '尚无数据' : `最短 ${cycleStats.min} · 最长 ${cycleStats.max} 天` }}</span></div><TrendChart title="周期长度趋势" :rows="cycleRows" unit="天" /><p class="hint">漏记或未明确出血的间隔不参与；预测始终使用最近最多 12 个有效周期。</p></section>
    <section class="card"><h2>经期持续天数</h2><TrendChart title="经期持续天数" :rows="periodStats.rows.map(p => ({ date: p.startDate,value: p.length }))" unit="天" color="#bc857d" /></section>
    <section class="card"><h2>每次经期的出血量</h2><p class="hint">只统计实际填写的等级；空白日期保留为未记录。</p><p v-if="!bodyCycles.flows.length" class="muted">完整经期留下记录后，会显示各等级的天数。</p><div v-for="p in bodyCycles.flows" :key="p.date" class="period-distribution"><button class="text-button" @click="openEditor(p.date)">{{ displayDate(p.date,true) }} 开始</button><p class="hint">{{ p.coveredDays }}/{{ p.totalDays }} 天填写</p><div class="chips"><span v-for="c in p.counts" :key="c.label">{{ c.label }} {{ c.count }} 天</span></div></div></section>
    <section class="card"><h2>出血颜色与周期日</h2><p class="hint">多选颜色分别计数；漏记间隔中的记录不参与定位。</p><p v-if="!bodyCycles.colors.length" class="muted">还没有可定位的颜色记录。</p><div v-for="r in bodyCycles.colors" :key="r.day" class="period-distribution"><strong>周期第 {{ r.day }} 天</strong><p class="hint">{{ r.coveredDays }} 天填写 · {{ r.counts.map(c => c.label + ' ' + c.count + ' 天').join('、') || '明确没有' }}</p><details class="explanation"><summary>查看来源日期</summary><div class="source-dates"><button v-for="date in r.dates" :key="date" class="text-button" @click="openEditor(date)">{{ displayDate(date,true) }}</button></div></details></div></section>
    <section class="card"><h2>疼痛与周期日</h2><p class="hint">至少覆盖 3 个可定位周期后展示；每个周期日单独列出实际覆盖数，未填不算 0 分。</p><p v-if="!bodyCycles.pains.length" class="muted">已覆盖 {{ bodyCycles.painAnchorCount }} 个可定位周期，继续记录后再比较。</p><div v-for="r in bodyCycles.pains" :key="r.day" class="period-distribution"><strong>周期第 {{ r.day }} 天 · 平均 {{ r.average.toFixed(1) }} 分</strong><p class="hint">{{ r.coveredDays }} 天填写 · 覆盖 {{ r.coveredCycles }} 个周期</p><details class="explanation"><summary>查看来源日期</summary><div class="source-dates"><button v-for="date in r.dates" :key="date" class="text-button" @click="openEditor(date)">{{ displayDate(date,true) }}</button></div></details></div></section>
    <section class="card evaluation-card"><div><h2>平均预测误差</h2><p v-if="mae.value !== null">已核实的 {{ mae.count }} 次预测，平均相差 <strong>{{ mae.value.toFixed(1) }} 天</strong>。</p><p v-else>还没有可核实的预测记录。</p><p class="hint">每个周期只采用第一次可用的基础日期预测；漏记、事实更正及过晚生成的样本不计入。</p></div><Icon name="leaf" :size="27" /></section>
  </template>
  <template v-if="tab === 'body'"><div class="section-heading row-between"><div><h2>身体记录</h2><p class="hint">{{ displayDate(start) }} — {{ displayDate(state.today) }} · {{ daily.rows.length }}/{{ route.days }} 天有记录</p></div><div class="chips range-chips"><button v-for="n in [30,90]" :key="n" :class="{ selected: route.days === n }" @click="rangeDays(n)">最近 {{ n }} 天</button></div></div>
    <p v-if="loading" class="hint">正在读取身体记录…</p><p v-if="error" class="form-error">{{ error }}</p>
    <div class="stats-grid"><section class="card stat-card"><span>疼痛自评分均值</span><strong>{{ fixed(daily.pain.average) }}<small>分</small></strong><p>{{ daily.pain.rows.length }} 天填写 · 0 分参与统计</p></section><section class="card stat-card"><span>睡眠时长均值</span><strong>{{ fixed(daily.sleep.average) }}<small>小时</small></strong><p>{{ daily.sleep.rows.length }} 天填写</p></section><section class="card stat-card"><span>排便／爱爱事件</span><strong>{{ daily.bowel.count }}<small>／</small>{{ daily.intimacy.count }}</strong><p>分别有 {{ daily.bowel.days }}／{{ daily.intimacy.days }} 天填写</p></section></div>
    <section class="card"><h2>疼痛的变化</h2><TrendChart title="疼痛自评分" :rows="daily.pain.rows.map(d => ({ date: d.date,value: d.painScore! }))" unit="分" color="#bc857d" /></section><section class="card"><h2>睡眠时长</h2><TrendChart title="睡眠时长" :rows="daily.sleep.rows.map(d => ({ date: d.date,value: d.sleepHours! }))" unit="小时" /></section>
    <div class="distribution-grid"><section v-for="d in daily.distributions" :key="d.title" class="card distribution-card"><h3>{{ d.title }}</h3><p class="hint">{{ d.coveredDays }}/{{ route.days }} 天填写{{ d.unit === '次' ? ` · ${d.denominator} 次分类记录` : '' }}</p><div v-for="count in d.counts" :key="count.label" class="distribution-row"><div class="row-between"><span>{{ count.label }}</span><strong>{{ count.count }} {{ d.unit }}<small v-if="d.unit === '天' && d.denominator"> · {{ (count.count / d.denominator * 100).toFixed(0) }}%</small></strong></div><div class="bar-track"><div :style="{ width: Math.min(100,count.count / Math.max(d.denominator,count.count) * 100) + '%' }" /></div></div><p v-if="!d.counts.length" class="muted">{{ d.coveredDays ? '有明确无记录，或未填写具体类别。' : '这个项目还没有记录。' }}</p><details v-if="d.dates.length" class="explanation"><summary>查看来源日期</summary><div class="source-dates"><button v-for="date in d.dates" :key="date" class="text-button" @click="openEditor(date)">{{ displayDate(date) }}</button></div></details></section></div>
    <section class="card"><h2>记录时间线</h2><p v-if="!daily.rows.length" class="muted">选择日历中的一天，开始填写身体感受。</p><button v-for="d in [...daily.rows].reverse()" :key="d.date" class="record-row" @click="openEditor(d.date)"><strong>{{ displayDate(d.date,true) }}</strong><span>{{ d.note || '查看这一天的身体记录' }}<Icon name="chevron" :size="16" /></span></button></section>
  </template>
  <template v-if="tab === 'observations'"><section class="card observation-intro"><Icon name="leaf" :size="25" /><div><h2>只和自己的历史比较</h2><p>周期与经期长度比较最近 3 次和此前 3 次；每日状态比较相邻两个 30 天窗口，每段至少有 7 天填写相关项目。</p></div></section>
    <section v-for="o in observations" :key="o.id" class="card observation-card"><span class="eyebrow">来自个人记录</span><h3>{{ o.text }}</h3><p v-for="(r,i) in o.ranges" :key="r" class="hint">{{ r }} · {{ o.sampleCounts[i] }} 个样本</p><details class="explanation"><summary>查看依据</summary><div class="source-dates"><button v-for="date in o.sourceDates" :key="date" class="text-button" @click="openEditor(date)">{{ displayDate(date,true) }}</button></div></details></section>
    <section v-if="!observations.length" class="card empty-state"><Icon name="leaf" :size="38" /><h2>规律，慢慢会清晰</h2><p>目前还不足以比较变化。已有图表和记录仍可查看。</p><a class="secondary-button" href="#/calendar">去日历记录</a></section>
  </template>
</div></template>
